#!/bin/sh
# Builds AKey.app (menu bar only: LSUIElement) and signs it ad-hoc.
# The .noindex folder keeps Spotlight from listing the build next to the installed app.
set -eu

cd "$(dirname "$0")/.."
VERSION=$(sed -n 's/^version = "\(.*\)"/\1/p' Cargo.toml | head -1)
APP=target/release/bundle.noindex/AKey.app

cargo build --release

rm -rf "$APP" target/release/akey.app
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp target/release/akey "$APP/Contents/MacOS/akey"
# Generated by scripts/make-icon.swift.
cp resources/AppIcon.icns "$APP/Contents/Resources/AppIcon.icns"

cat > "$APP/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleIdentifier</key>          <string>com.phumiphat.akey</string>
    <key>CFBundleName</key>                <string>AKey</string>
    <key>CFBundleDisplayName</key>         <string>AKey</string>
    <key>CFBundleExecutable</key>          <string>akey</string>
    <key>CFBundleIconFile</key>            <string>AppIcon</string>
    <key>CFBundlePackageType</key>         <string>APPL</string>
    <key>CFBundleShortVersionString</key>  <string>${VERSION}</string>
    <key>CFBundleVersion</key>             <string>${VERSION}</string>
    <key>CFBundleInfoDictionaryVersion</key><string>6.0</string>
    <key>LSMinimumSystemVersion</key>      <string>14.0</string>
    <key>LSUIElement</key>                 <true/>
    <key>NSHighResolutionCapable</key>     <true/>
</dict>
</plist>
PLIST

codesign --force --sign - --identifier com.phumiphat.akey "$APP"
echo "Built $APP ($(du -h "$APP/Contents/MacOS/akey" | cut -f1) binary)"
